# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_260'] || []

# Conditions applied to each ELEMENT of the collection this check judges.
# An element matches when EVERY condition holds; a condition holds when SOME
# value reachable at ANY of its paths satisfies the test. `when_absent` is the
# verdict when a path reaches nothing at all, which is how a member the API
# omits is given its documented meaning. Generated from resource_map.yml by
# tools/render_controls.py; the walk is libraries/_checkov_collection.rb.
element_conditions = [
  # from_port <= 80 (or absent)
  { paths: ['from_port'],
    when_absent: true,
    test: ->(v) { v <= 80 } },
  # to_port >= 80 (or absent)
  { paths: ['to_port'],
    when_absent: true,
    test: ->(v) { v >= 80 } },
  # (ip_ranges.cidr_ip or ipv_6_ranges.cidr_ipv_6) is one of [0.0.0.0/0, ::/0, 0000:0000:0000:0000:0000:0000:0000:0000/0]
  { paths: ['ip_ranges.cidr_ip', 'ipv_6_ranges.cidr_ipv_6'],
    test: ->(v) { ['0.0.0.0/0', '::/0', '0000:0000:0000:0000:0000:0000:0000:0000/0'].include?(v) } },
].freeze

control 'CKV_AWS_260' do
  title 'Ensure no security groups allow ingress from 0.0.0.0:0 to port 80'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_security_group resources that actually exist, enumerated through
    the declarative API spec.

    Checkov reads Terraform, so a rule added in the console, by a second
    pipeline or by an incident responder during an outage is invisible to
    it. This reads the permissions EC2 is actually enforcing, whatever
    created them.
  DESC

  desc 'rationale', <<~RATIONALE
    Port 80 is cleartext HTTP, so anything reachable on it is reachable
    without transport confidentiality or server authentication, and
    world-open means reachable by every host on the internet rather than by
    a load balancer in front of it. Rated medium rather than high because a
    public web tier deliberately terminating a redirect on 80 is a
    legitimate design; the finding is that the security group cannot tell
    that case from an application server left directly exposed, and only the
    operator can.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_security_group: an INGRESS permission whose
    from_port..to_port span covers 80 — or which carries no port members at
    all, which is how AWS stores an all-protocols rule — and whose IpRanges
    contain 0.0.0.0/0 or whose Ipv6Ranges contain ::/0.
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_security_group:

      resource "aws_security_group" "web" {
        name   = "web"
        vpc_id = aws_vpc.example.id

        # HTTP arrives from the load balancer's security group, never from a
        # CIDR. There is no ingress block carrying cidr_blocks = ["0.0.0.0/0"];
        # the public edge is the ALB, and it is the only thing that should be
        # able to reach 80 here.
        ingress {
          description     = "HTTP from the public ALB"
          from_port       = 80
          to_port         = 80
          protocol        = "tcp"
          security_groups = [aws_security_group.alb.id]
        }
      }

    Out of band — aws_security_group:

      aws ec2 revoke-security-group-ingress --group-id <sg-id> --protocol tcp --port 80 --cidr 0.0.0.0/0
      aws ec2 revoke-security-group-ingress --group-id <sg-id> --ip-permissions IpProtocol=tcp,FromPort=80,ToPort=80,Ipv6Ranges=[{CidrIpv6=::/0}]

    Note (aws_security_group): The revoke closes the exposure now and the next
    terraform apply reopens it if the HCL still carries the rule, so the CLI is
    containment and the Terraform change is the fix. A permission whose range
    merely SPANS 80 — 0-65535, or an IpProtocol of "-1", which AWS stores with
    no ports at all — must be revoked with the range it was created with, not
    with --port 80. If the world genuinely must reach 80, put an ALB in front
    and move the rule to the ALB's security group rather than widening this one.
  FIX

  tag checkov_id:            'CKV_AWS_260'
  tag checkov_category:      'NETWORKING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_security_group aws_security_group_rule aws_vpc_security_group_ingress_rule]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/security_group'
  tag nist:                  ['SC-7', 'SC-7 (5)']
  tag nist_r4:               ['SC-7', 'SC-7 (5)']
  tag cci:                   ['CCI-001097', 'CCI-002080']
  tag ksi:                   ['KSI-CNA-NDS']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_security_group', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
  # one with nothing in it. A missing SDK gem, a denied call or an unreachable
  # endpoint all end up here, and without this assertion they render as "no
  # assets" and the control reports Not Applicable: the worst case reported as
  # "does not apply here".
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe "aws_security_group enumeration" do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # A blank id means the spec's `id` column names a member this response does
  # not carry. tools/lint_resource_map.py cannot see that statically, and the
  # damage is silent: every describe is titled with a blank where the identity
  # belongs, and `exempt_assets` entries keyed by id stop matching. Asserted,
  # not filtered — filtering renders Not Applicable, which is the same silence.
  enumerated = assets.assets(exempt: exempt)
  unusable = enumerated.count { |a| "#{a[:id]}".strip.empty? }
  if unusable.positive?
    describe "aws_security_group enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `id` for aws_security_group in "\
          'tools/api_specs.yml likely names a member this API does not return'
      end
    end
  end

  # A collection roll-up is not nil-filtered: an asset that does not
  # express the field is part of the population the guard below counts,
  # and for any_of it is precisely the failing case.
  in_scope = enumerated

  # none_of is vacuously TRUE over an empty collection, so an asset that did
  # not carry this field passes without being examined. For one asset with no
  # elements that is the right answer; when it is EVERY asset the control can no
  # longer fail, and a control that cannot fail reads as compliant rather than as
  # a mapping naming a field this API does not return. The condition paths one
  # level down are checked statically instead — tools/lint_api_paths.rb.
  exposing = in_scope.count { |a| !a[:ip_permissions].nil? }

  describe 'aws_security_group ip_permissions' do
    it 'was returned for at least one asset in scope' do
      expect(exposing).to be_positive,
        'no asset in scope exposed ip_permissions, so the roll-up below cannot fail: '\
        'either tools/api_specs.yml names a field this API does not return, or '\
        'nothing in this boundary expresses it'
    end
  end

  # `applicable` is a CLAIM that this rule does not apply to this boundary, and
  # only an enumeration that succeeded can earn it. An unreadable region or a
  # blank id column keeps the control applicable so the assertions above are
  # reported; without that, only_if skips the whole control — the two guards
  # included — and the worst case, "every region denied", renders as Not
  # Applicable. The stock template already carries the `unusable` half of this.
  applicable = !in_scope.empty? || !unreadable.empty? || unusable.positive?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_security_group in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_security_group #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:ip_permissions] }
      it { should satisfy("have no element where from_port <= 80 (or absent) and to_port >= 80 (or absent) and (ip_ranges.cidr_ip or ipv_6_ranges.cidr_ipv_6) is one of [0.0.0.0/0, ::/0, 0000:0000:0000:0000:0000:0000:0000:0000/0]") { |v| ::CheckovCollection.none_of?(v, element_conditions) } }
    end
  end
